    "home.closing.disclaimer": "प्रारंभिक दृश्य में बावली एक प्रक्रियात्मक रूप से तैयार किया गया निदर्शी मॉडल है, किसी विशिष्ट स्थल का सर्वेक्षण नहीं।",
    "home.closing.lead": "जो प्रलेखित किया जा सकता है उससे शुरुआत करें। उसे पारंपरिक ज्ञान से जोड़ें।",
    "home.closing.product": "उत्पाद",
    "home.closing.tagline": "भारत की पारंपरिक जल संरचनाओं के लिए एआई-सहायक डिजिटल संरक्षण। जलदृष्टि योग्य पेशेवरों के आकलन का समर्थन करती है, उसका स्थान नहीं लेती।",
