    "home.diversity.templeBody": "मंदिर परिसरों के भीतर या पास स्थित तालाब, जो अक्सर चारों तरफ सीढ़ीदार होते हैं और धार्मिक व सामाजिक जीवन से जुड़े होते हैं।",
