    "home.material.body": "संरक्षण संबंधी निर्णय केवल सतह की उपस्थिति पर निर्भर नहीं करते। मौजूदा सामग्री, निर्माण, नमी और जल निकासी सभी विचारणीय हैं।",
    "home.material.caveat": "यह उदाहरण प्रलेखित सामग्री गुणों के आधार पर दो मोर्टार की तुलना करता है, न कि प्रयोगशाला परीक्षणों पर।",
