    "home.doc.body": "দৃশ্যমান ক্ষতি নানা রূপ নিতে পারে: ফাটল, ক্ষয়, আর্দ্রতা, উদ্ভিদ বৃদ্ধি বা আগের মেরামতের দাগ। ভালো নথিবদ্ধকরণ সংরক্ষণের সঠিক সূচনা বিন্দু তৈরি করে।",
