    "hero.chapter1.rail": "ସ୍ଥାନ",
    "hero.chapter1.title": "ଜଳ ଐତିହ୍ୟ ଏହାର ପ୍ରାକୃତିକ ପରିଦୃଶ୍ୟ ସହିତ ଜଡ଼ିତ।",
    "hero.chapter2.body": "ଢାଲୁ, ଜଳଗ୍ରହଣ କ୍ଷେତ୍ର ଏବଂ ସୁରକ୍ଷା କାନ୍ଥ ନିର୍ଣ୍ଣୟ କରେ ଯେ ଜଳ କିପରି ପହଞ୍ଚେ, କିପରି ସଂରକ୍ଷିତ ହୁଏ ଏବଂ କିପରି ବ୍ୟବହୃତ ହୁଏ।",
    "hero.chapter2.label": "୦୨ / ଦୃଷ୍ଟିକୋଣ",
    "hero.chapter2.rail": "ଦୃଷ୍ଟିକୋଣ",
    "hero.chapter2.title": "ସଂରଚନା, ଭୂମି ଏବଂ ଜଳ ଏକତ୍ର କାର୍ଯ୍ୟ କରନ୍ତି।",
    "hero.chapter3.body": "ସିଡ଼ି, ଚଟାଣ ଏବଂ ସୁରକ୍ଷା କାନ୍ଥ ପ୍ରମାଣ ଦିଏ ଯେ ସଂରଚନାଟି କିପରି ଡିଜାଇନ୍ ଏବଂ ବ୍ୟବହୃତ ହୋଇଥିଲା।",
    "hero.chapter3.label": "୦୩ / ଅବତରଣ",
    "hero.chapter3.rail": "ଅବତରଣ",
    "hero.chapter3.title": "ଡକ୍ୟୁମେଣ୍ଟେସନ୍ ସନ୍ଦର୍ଭ ସହିତ ଆରମ୍ଭ ହୁଏ।",
    "hero.chapter4.body": "ପଥର ଯୋଡ଼େଇ, କ୍ଷୟପ୍ରାପ୍ତ ପୃଷ୍ଠଭୂମି ଏବଂ ପରବର୍ତ୍ତୀ ମରାମତି ବିଭିନ୍ନ କାହାଣୀ କୁହନ୍ତି। ସଠିକ୍ ରେକର୍ଡ ମୂଳ ଏବଂ ପରିବର୍ତ୍ତିତ ଅଂଶକୁ ପୃଥକ କରିବାରେ ସାହାଯ୍ୟ କରେ।",
    "hero.chapter4.label": "୦୪ / କଳା ଓ ଶିଳ୍ପ",
    "hero.chapter4.rail": "ଶିଳ୍ପ",
    "hero.chapter4.title": "ସାମଗ୍ରୀଗୁଡ଼ିକର ଯତ୍ନପୂର୍ବକ ବ୍ୟାଖ୍ୟା ଆବଶ୍ୟକ।",
    "hero.chapter5.body": "ଆର୍ଦ୍ରତା, ଜଳ ନିଷ୍କାସନ, ଉଦ୍ଭିଦ ଏବଂ ଆଖପାଖର ପରିବେଶ ସମୟ ସହିତ ଐତିହାସିକ ଜଳ ସଂରଚନାକୁ ପ୍ରଭାବିତ କରେ।",
    "hero.chapter5.label": "୦୫ / ଜଳ",
    "hero.chapter5.rail": "ଜଳ",
    "hero.chapter5.title": "ଦୃଶ୍ୟମାନ ପ୍ରମାଣ ଏବଂ ବ୍ୟାପକ ପ୍ରଶ୍ନ।",
    "hero.chapter6.body": "ବାଓଲି ଏବଂ କୁଣ୍ଡଠାରୁ ଆରମ୍ଭ କରି ଐତିହାସିକ ଜଳାଶୟ ପର୍ଯ୍ୟନ୍ତ, ଜଳଦୃଷ୍ଟି ଡିଜିଟାଲ୍ ଡକ୍ୟୁମେଣ୍ଟେସନ୍, ପାରମ୍ପରିକ ଜ୍ଞାନ ଏବଂ ସଂରକ୍ଷଣ ମାର୍ଗଦର୍ଶନକୁ ଏକତ୍ର କରେ।",
    "hero.chapter6.label": "୦୬ / ଜଳଦୃଷ୍ଟି",
    "hero.chapter6.rail": "ମିଶନ",
    "hero.chapter6.title": "ଏକ ଉଦାହରଣ। ଏକ ବ୍ୟାପକ ଐତିହ୍ୟ।",
    "hero.explore": "ଜଳଦୃଷ୍ଟି ଅନୁସନ୍ଧାନ କରନ୍ତୁ",
    "hero.exploreKnowledge": "ଜ୍ଞାନ ଅନୁସନ୍ଧାନ କରନ୍ତୁ",
    "hero.lead": "ବାଓଲି ଏବଂ କୁଣ୍ଡଠାରୁ ଆରମ୍ଭ କରି ଐତିହାସିକ ଜଳାଶୟ ଏବଂ ପାରମ୍ପରିକ ଜଳ ପ୍ରଣାଳୀ ପର୍ଯ୍ୟନ୍ତ, ଭାରତର ଜଳ ଐତିହ୍ୟ ସ୍ଥାପତ୍ୟ, ପରିବେଶ ଏବଂ ସାଂସ୍କୃତିକ ଜ୍ଞାନ ବହନ କରେ। ଜଳଦୃଷ୍ଟି ଏହାର ଡକ୍ୟୁମେଣ୍ଟେସନ୍ ଏବଂ ସଂରକ୍ଷଣକୁ ସମର୍ଥନ କରେ।",
    "hero.scrollDescend": "ତଳକୁ ଯିବା ପାଇଁ ସ୍କ୍ରୋଲ୍ କରନ୍ତୁ",
