    "historical.verified": "ସ୍ଥପତି ଦ୍ୱାରା ପ୍ରମାଣିତ",
    "home.closing.disclaimer": "ପ୍ରାରମ୍ଭିକ ଦୃଶ୍ୟରେ ଥିବା ବାଓଲି ଏକ ପ୍ରକ୍ରିୟାଗତ ନମୁନା ମଡେଲ୍, କୌଣସି ନିର୍ଦ୍ଦିଷ୍ଟ ସ୍ଥଳର ସର୍ଭେ ନୁହେଁ।",
    "home.closing.lead": "ଯାହା ଡକ୍ୟୁମେଣ୍ଟ ହୋଇପାରିବ ତାହାଠାରୁ ଆରମ୍ଭ କରନ୍ତୁ। ତାହାକୁ ପାରମ୍ପରିକ ଜ୍ଞାନ ସହ ଯୋଡ଼ନ୍ତୁ।",
    "home.closing.product": "ଉତ୍ପାଦ",
    "home.closing.tagline": "ଭାରତର ପାରମ୍ପରିକ ଜଳ ସଂରଚନା ପାଇଁ ଏଆଇ-ସହାୟକ ଡିଜିଟାଲ୍ ସଂରକ୍ଷଣ। ଜଳଦୃଷ୍ଟି ଯୋଗ୍ୟ ବିଶେଷଜ୍ଞଙ୍କ ମୂଲ୍ୟାଙ୍କନକୁ ସମର୍ଥନ କରେ, ଏହାର ବିକଳ୍ପ ନୁହେଁ।",
    "home.closing.team": "ଦଳ",
    "home.closing.teamCredits": "ଭିଜନ୍ · ଇଞ୍ଜିନିୟରିଂ ଏବଂ ଆଇକେଏସ୍ · ବ୍ୟାକଏଣ୍ଡ୍ · ଫ୍ରଣ୍ଟଏଣ୍ଡ୍",
    "home.closing.title": "ଭାରତର ଜଳ ଐତିହ୍ୟକୁ ଡକ୍ୟୁମେଣ୍ଟ କରନ୍ତୁ।",
    "home.diversity.footerNote": "ଯୋଜନାବଦ୍ଧ ଚିତ୍ର, ସଠିକ୍ ସ୍କେଲ୍ ଅନୁଯାୟୀ ନୁହେଁ। ଆଞ୍ଚଳିକ ନାମ ଭିନ୍ନ ହୋଇପାରେ।",
    "home.diversity.kunds": "କୁଣ୍ଡ",
    "home.diversity.kundsBody": "ବର୍ଷା ଜଳ ସଂଗ୍ରହ ପାଇଁ ପାହାଚିଆ ଜଳାଶୟ, ଯାହା ପ୍ରାୟତଃ ଓଲଟା ପିରାମିଡ୍ ଆକାରର।",
    "home.diversity.kundsTerms": "କୁଣ୍ଡ · କୁଣ୍ଡା · କୁଣ୍ଡି",
    "home.diversity.label": "ଏକ ବିବିଧ ଜଳ ଐତିହ୍ୟ",
    "home.diversity.lead": "ଭାରତର ବିଭିନ୍ନ ପ୍ରାନ୍ତରେ ପାରମ୍ପରିକ ଜଳ ସଂରଚନା ବିଭିନ୍ନ ରୂପ ନିଏ। ବାଓଲି, କୁଣ୍ଡ, ଟାଙ୍କି ଏବଂ ପୋଖରୀ ସ୍ଥାନୀୟ ଭୂଗୋଳ ଏବଂ ପରମ୍ପରା ସହିତ ସମନ୍ୱିତ।",
    "home.diversity.ponds": "ପୋଖରୀ ଏବଂ ଆଞ୍ଚଳିକ ବ୍ୟବସ୍ଥା",
    "home.diversity.pondsBody": "ମାଟି ବନ୍ଧ ଏବଂ ଗ୍ରାମ୍ୟ ପୋଖରୀ, ଯାହା ସ୍ଥାନୀୟ ଭୂଭାଗ ଅନୁଯାୟୀ ଜଳ ସଂରକ୍ଷଣ ପାଇଁ ଉଦ୍ଦିଷ୍ଟ।",
    "home.diversity.pondsTerms": "ଜୋହାଡ଼ · ପୋଖରୀ · ସ୍ଥାନୀୟ ନାମ",
    "home.diversity.stepwells": "ବାଓଲି / ଷ୍ଟେପୱେଲ",
    "home.diversity.stepwellsBody": "ଭୂତଳ ଜଳ ପର୍ଯ୍ୟନ୍ତ ପାହାଚିଆ ଅବତରଣ, ଯେଉଁଥିରେ ଚଟାଣ, ସୁରକ୍ଷା କାନ୍ଥ ଏବଂ କୂଅ ଅନ୍ତର୍ଭୁକ୍ତ।",
    "home.diversity.stepwellsTerms": "ବାଓଲି · ବାୱଡ଼ି · ଭାବ୍",
    "home.diversity.tagScope": "ଲକ୍ଷ୍ୟଭୁକ୍ତ ପରିସୀମା ମଧ୍ୟରେ",
    "home.diversity.tagToday": "ବର୍ତ୍ତମାନର ଜ୍ଞାନ ରେକର୍ଡ",
    "home.diversity.tanks": "ଐତିହାସିକ ଜଳାଶୟ ଏବଂ ଟାଙ୍କି",
    "home.diversity.tanksBody": "ଋତୁକାଳୀନ ଜଳ ସଂରକ୍ଷଣ କରୁଥିବା ବନ୍ଧଯୁକ୍ତ ଜଳାଶୟ, ଯେଉଁଥିରେ ଘାଟ ଏବଂ ଜଳ ନିୟନ୍ତ୍ରଣ ଦ୍ୱାର ରହିଥାଏ।",
    "home.diversity.tanksTerms": "ତାଲାବ · ସାଗର · ଏରି",
    "home.diversity.temple": "ମନ୍ଦିର ପୋଖରୀ",
    "home.diversity.templeBody": "ମନ୍ଦିର ପରିସର ମଧ୍ୟରେ ବା ନିକଟରେ ଥିବା ପୋଖରୀ, ଯାହା ଚାରିପାଖରେ ପାହାଚଯୁକ୍ତ ଏବଂ ଧାର୍ମିକ ଜୀବନ ସହ ଜଡ଼ିତ।",
    "home.diversity.templeTerms": "କଲ୍ୟାଣୀ · ପୁଷ୍କରିଣୀ",
    "home.diversity.title": "ଏକ ଐତିହ୍ୟ। ଅନେକ ରୂପ। ସ୍ୱତନ୍ତ୍ର ସ୍ଥାନୀୟ ଜ୍ଞାନ।",
    "home.doc.assess": "ଆକଳନ",
    "home.doc.assessLine": "ସାମଗ୍ରୀ ଏବଂ ହସ୍ତକ୍ଷେପଗୁଡ଼ିକର ବିଚାର କରନ୍ତୁ।",
    "home.doc.body": "ଦୃଶ୍ୟମାନ କ୍ଷତିର ଅନେକ ରୂପ ଥାଇପାରେ: ଫାଟ, ପଥର କ୍ଷୟ, ଆର୍ଦ୍ରତା, ଅନାବନା ଉଦ୍ଭିଦ କିମ୍ବା ପୁରୁଣା ମରାମତିର ଚିହ୍ନ। ଉତ୍ତମ ଡକ୍ୟୁମେଣ୍ଟେସନ୍ ସଂରକ୍ଷଣର ଏକ ସ୍ପଷ୍ଟ ପ୍ରାରମ୍ଭିକ ବିନ୍ଦୁ ସୃଷ୍ଟି କରେ।",
    "home.doc.caption": "ପଥର କାନ୍ଥର ଚିତ୍ରାତ୍ମକ ବିବରଣୀ · ଦୃଶ୍ୟମାନ ଚିହ୍ନ କେବଳ ରେକର୍ଡର ଆରମ୍ଭ, ରୋଗ ନିର୍ଣ୍ଣୟର ଶେଷ ନୁହେଁ।",
