    "home.revive.body": "ହସ୍ତକ୍ଷେପଗୁଡ଼ିକ ପ୍ରତ୍ୟାବର୍ତ୍ତନୀୟ ଏବଂ ମୂଳ ସାମଗ୍ରୀ ସହିତ ସୁସଙ୍ଗତ ହେବା ଉଚିତ।",
