    "historical.selectStructure": "কাঠামো নির্বাচন করুন",
    "historical.subtitle": "বাধ্যতামূলক সংরক্ষণ স্থপতির অনুমোদনের সাথে ঐতিহাসিক জরিপ নথির স্থায়ী ত্রুটি পাসপোর্টে রূপান্তর।",
