    "hero.beginInspection": "निरीक्षण शुरू करें",
    "hero.chapter1.body": "बावली, कुंड, मंदिर का तालाब या ग्रामीण पोखर: प्रत्येक अपनी भूमि, जलवायु और समुदाय के भीतर स्थित है। किसी भी जल संरचना को समझने की शुरुआत उसकी संरचना से परे देखने से होती है।",
    "hero.chapter1.label": "01 / स्थान",
    "hero.chapter1.rail": "स्थान",
    "hero.chapter1.title": "जल विरासत अपने प्राकृतिक परिदृश्य से जुड़ी है।",
    "hero.chapter2.body": "ढलान, जलग्रहण क्षेत्र और सुरक्षात्मक दीवारें तय करती हैं कि पानी कैसे पहुंचता है, कैसे रुकता है और उस तक कैसे पहुंचा जाता है।",
    "hero.chapter2.label": "02 / दृष्टिकोण",
    "hero.chapter2.rail": "दृष्टिकोण",
    "hero.chapter2.title": "संरचना, भूमि और जल मिलकर कार्य करते हैं।",
    "hero.chapter3.body": "सीढ़ियां, चबूतरे और ढलान वाली दीवारें दर्शाती हैं कि संरचना को कैसे डिजाइन और उपयोग किया गया था। संदर्भ सहित प्रलेखन प्रत्येक अवलोकन को स्पष्ट आधार प्रदान करता है।",
    "hero.chapter3.label": "03 / अवतरण",
    "hero.chapter3.rail": "अवतरण",
    "hero.chapter3.title": "प्रलेखन का आरंभ संदर्भ के साथ होता है।",
    "hero.chapter4.body": "चिनाई के जोड़, घिसी हुई सतहें और बाद की मरम्मतें विभिन्न कहानियां बताती हैं। एक सटीक रिकॉर्ड मूल और परिवर्तित संरचना को अलग करने में मदद करता है।",
    "hero.chapter4.label": "04 / शिल्प",
    "hero.chapter4.rail": "शिल्प",
    "hero.chapter4.title": "सामग्रियों की सावधानीपूर्वक व्याख्या आवश्यक है।",
    "hero.chapter5.body": "नमी, जल निकासी, वनस्पति और आसपास का वातावरण समय के साथ ऐतिहासिक जल संरचनाओं को प्रभावित करते हैं। कारण समझने के लिए स्थलीय जांच आवश्यक है।",
    "hero.chapter5.label": "05 / जल",
    "hero.chapter5.rail": "जल",
    "hero.chapter5.title": "दृश्य प्रमाण और व्यापक प्रश्न।",
    "hero.chapter6.body": "बावलियों और कुंडों से लेकर ऐतिहासिक तालाबों तक, जलदृष्टि डिजिटल प्रलेखन, पारंपरिक ज्ञान और संरक्षण मार्गदर्शन को एक साथ लाती है।",
    "hero.chapter6.label": "06 / जलदृष्टि",
    "hero.chapter6.rail": "मिशन",
    "hero.chapter6.title": "एक उदाहरण। एक व्यापक जल विरासत।",
    "hero.explore": "जलदृष्टि का अन्वेषण करें",
    "hero.exploreKnowledge": "ज्ञान का अन्वेषण करें",
    "hero.lead": "बावड़ियों और कुंडों से लेकर ऐतिहासिक तालाबों और पारंपरिक जल प्रणालियों तक, भारत की जल विरासत स्थापत्य, पर्यावरण और सांस्कृतिक ज्ञान संजोए हुए है। जलदृष्टि इसके प्रलेखन और संरक्षण में सहयोग करती है।",
    "hero.scrollDescend": "नीचे उतरने के लिए स्क्रॉल करें",
