    "home.closing.title": "भारत की जल विरासत का प्रलेखन करें।",
    "home.diversity.footerNote": "योजनाबद्ध खंड और योजनाएं, पैमाने के अनुसार नहीं। क्षेत्रीय नाम भिन्न हो सकते हैं।",
    "home.diversity.kunds": "कुंड",
    "home.diversity.kundsBody": "वर्षा जल संचयन के लिए सीढ़ीदार जलाशय, जो अक्सर चारों ओर पक्के जलग्रहण क्षेत्र के साथ उलटे पिरामिड के आकार के होते हैं।",
    "home.diversity.kundsTerms": "कुंड · कुंडा · कुंडी",
    "home.diversity.label": "एक विविध जल विरासत",
    "home.diversity.lead": "पूरे भारत में पारंपरिक जल संरचनाएं विभिन्न रूपों में पाई जाती हैं। बावलियां, कुंड, तालाब और पोखर विभिन्न परिदृश्यों और सामग्रियों के अनुकूल हैं।",
    "home.diversity.ponds": "पोखर और क्षेत्रीय प्रणालियां",
    "home.diversity.pondsBody": "मिट्टी के तटबंध और ग्रामीण पोखर, जो स्थानीय भूभाग और प्रथाओं के आधार पर पानी के संचयन और वितरण के लिए बनाए गए हैं।",
