    "home.diversity.title": "एक विरासत। अनेक रूप। विशिष्ट स्थानीय ज्ञान।",
    "home.doc.assess": "आकलन",
    "home.doc.assessLine": "सामग्रियों और हस्तक्षेपों का मूल्यांकन करें।",
    "home.doc.body": "दृश्य क्षति के कई रूप हो सकते हैं: दरारें, उखड़ा हुआ पत्थर, नमी, वनस्पति, या पुरानी मरम्मत के निशान। अच्छा प्रलेखन संरक्षण का सटीक आरंभिक बिंदु बनाता है।",
    "home.doc.caption": "चिनाई का चित्रात्मक विवरण · दृश्य संकेत केवल प्रलेखन की शुरुआत हैं, निदान का अंत नहीं।",
